-- X05-T1 — WhatsApp channel adapter, module registration.
-- Widens the two `channel` check constraints (delivery_attempts: 0003,
-- notification_preferences: 0068) to accept 'whatsapp', and registers the
-- `whatsapp` module key in app.module_catalog (0084 MOD-T12). The
-- `notification_preferences_category_check` constraint (0074 M12) is a
-- separate constraint on a different column and is left untouched.
--
-- Constraint names are looked up via pg_constraint/pg_attribute (keyed on
-- the `channel` column) rather than hardcoded, since they are
-- Postgres-autogenerated and this file must not assume the exact name.

do $$
declare
  v_name text;
begin
  select con.conname into v_name
  from pg_constraint con
  join pg_attribute att on att.attrelid = con.conrelid and att.attnum = con.conkey[1]
  where con.conrelid = 'public.delivery_attempts'::regclass
    and con.contype = 'c'
    and array_length(con.conkey, 1) = 1
    and att.attname = 'channel';

  if v_name is null then
    raise exception 'delivery_attempts channel check constraint not found';
  end if;

  execute format('alter table public.delivery_attempts drop constraint %I', v_name);
end $$;

alter table public.delivery_attempts
  add constraint delivery_attempts_channel_check
  check (channel in ('in_app', 'sms', 'email', 'whatsapp'));

do $$
declare
  v_name text;
begin
  select con.conname into v_name
  from pg_constraint con
  join pg_attribute att on att.attrelid = con.conrelid and att.attnum = con.conkey[1]
  where con.conrelid = 'public.notification_preferences'::regclass
    and con.contype = 'c'
    and array_length(con.conkey, 1) = 1
    and att.attname = 'channel';

  if v_name is null then
    raise exception 'notification_preferences channel check constraint not found';
  end if;

  execute format('alter table public.notification_preferences drop constraint %I', v_name);
end $$;

alter table public.notification_preferences
  add constraint notification_preferences_channel_check
  check (channel in ('sms', 'email', 'whatsapp'));

insert into app.module_catalog (key, default_enabled) values ('whatsapp', true)
on conflict (key) do update set default_enabled = excluded.default_enabled;
